<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>Cara o cruz</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #fff8e1; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h2 id="title">Cara o cruz</h2>
  <h1 id="face">🪙</h1>
  <button id="flip">Lanzar</button>
  <p id="stats">Cara: 0 / Cruz: 0</p>
  <script>
    var h, tl;

    function mathRandomInt(a, b) {
      if (a > b) {
        // Swap a and b to ensure a is smaller.
        var c = a;
        a = b;
        b = c;
      }
      return Math.floor(Math.random() * (b - a + 1) + a);
    }

    document.getElementById("flip").addEventListener('click', function () {
      if (mathRandomInt(1, 2) == 1) {
        h = (typeof h === 'number' ? h : 0) + 1;
        document.getElementById("face").textContent = 'Cara';
      } else {
        tl = (typeof tl === 'number' ? tl : 0) + 1;
        document.getElementById("face").textContent = 'Cruz';
      }
      document.getElementById("stats").textContent = ['Cara: ',h,' / Cruz: ',tl].join('');
    });

    h = 0;
    tl = 0;
  </script>
</body>
</html>
```

