<!DOCTYPE html>
<html lang="ko">
<head>
  <meta charset="UTF-8">
  <title>신호등 게임</title>
  <style>
    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #ffffff; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
  </style>
</head>
<body>
  <div id="light" class="box" style="background:#ef4444">
    <h2 id="lt">빨강</h2>
  </div>
  <button id="cross">건너기</button>
  <p id="sc">점수: 0</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    var k, s;

    __timers.push(setInterval(function () {
      k = (typeof k === 'number' ? k : 0) + 1;
      if (k > 2) {
        k = 0;
      }
      document.getElementById("light").style.background = ["#ef4444", "#facc15", "#22c55e"][((k + 1) - 1)];
      document.getElementById("lt").textContent = ['빨강', '노랑', '초록'][((k + 1) - 1)];
    }, 2000));
    document.getElementById("cross").addEventListener('click', function () {
      if (k == 2) {
        s = (typeof s === 'number' ? s : 0) + 1;
        document.getElementById("sc").textContent = '점수: ' + String(s);
      } else if (k == 0) {
        __timers.forEach(clearInterval);
        __show("cross", "hide");
        document.getElementById("sc").textContent = '게임 오버! 최종 점수: ' + String(s);
      }
    });

    k = 0;
    s = 0;
  </script>
</body>
</html>
```

